package com.sami.app.sales.document;
import com.sami.app.common.api.ApiResponse; import com.sami.app.sales.document.SalesDocumentDtos.*; import jakarta.validation.Valid; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/sales-documents") @RequiredArgsConstructor public class SalesDocumentController { private final SalesDocumentService service; @GetMapping @PreAuthorize("@authz.has('sales:view')") public ApiResponse<List<Response>> list(@RequestParam Long companyId,@RequestParam Long branchId,@RequestParam(required=false) SalesDocumentType documentType){return ApiResponse.ok(service.list(companyId,branchId,documentType));} @GetMapping("/{id}") @PreAuthorize("@authz.has('sales:view')") public ApiResponse<Response> get(@PathVariable Long id){return ApiResponse.ok(service.get(id));} @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("@authz.has('sales:create')") public ApiResponse<Response> create(@Valid @RequestBody Request r){return ApiResponse.ok(service.create(r));} @PutMapping("/{id}") @PreAuthorize("@authz.has('sales:edit')") public ApiResponse<Response> update(@PathVariable Long id,@Valid @RequestBody Request r){return ApiResponse.ok(service.update(id,r));} @PostMapping("/{id}/issue") @PreAuthorize("@authz.has('sales:confirm')") public ApiResponse<Response> issue(@PathVariable Long id){return ApiResponse.ok(service.issue(id));} @PostMapping("/{id}/cancel") @PreAuthorize("@authz.has('sales:edit')") public ApiResponse<Response> cancel(@PathVariable Long id){return ApiResponse.ok(service.cancel(id));} @PostMapping("/{id}/expire") @PreAuthorize("@authz.has('sales:edit')") public ApiResponse<Response> expire(@PathVariable Long id){return ApiResponse.ok(service.expire(id));} @GetMapping("/{id}/audit") @PreAuthorize("@authz.has('sales:view-audit')") public ApiResponse<List<AuditResponse>> audit(@PathVariable Long id){return ApiResponse.ok(service.auditHistory(id));} }
